const b=$input.first().json.body||{};if(b.secret!=='sv-mail-2026-09-17-Kq7'){throw new Error('bad secret');}
if(!b.summary||!b.start||!b.end||!Array.isArray(b.attendees)||!b.attendees.length){throw new Error('missing fields');}
// house rules (user 21 Sep): every meeting has the founder, the investor, Aditya, Shradha and the startup's owner
const OWNER={aditya:'investors@sidanaventures.com',chaman:'dealflow@sidanaventures.com',akansha:'akansha@sidanaventures.com',shradha:'shradhaa@sidanaventures.com'};
const ow=OWNER[String(b.owner||'').trim().toLowerCase()];if(!ow){throw new Error('owner must be one of Aditya, Chaman, Akansha, Shradha');}
const ext=b.attendees.map(e=>String(e).trim().toLowerCase()).filter(e=>!/@sidanaventures\.com$/.test(e));
if(b.internal_only!==true&&ext.length<(b.internal===true?1:2)){throw new Error(b.internal===true?'internal meeting needs the founder':'need both the founder and the investor as attendees');}
// 28 Sep 2026 (Aditya): "in all the meeting booked chaman, aditya and shradhaa, founder and investor should be there - its a compulsion in all deal flow meeting."
// CHAMAN IS NOW FIXED, NOT CONDITIONAL ON OWNING THE DEAL. Before this the node added Aditya, Shradhaa and 'the owner', so on every
// Akansha- or Shradhaa-owned deal Chaman was silently absent - which is the gap being closed. Do not make this depend on the caller.
const FIXED=['investors@sidanaventures.com','shradhaa@sidanaventures.com','dealflow@sidanaventures.com'];
const att=[...new Set(b.attendees.concat(FIXED).concat([ow]).map(e=>String(e).trim().toLowerCase()))];
// hard pre-send check: an invite that does not carry all five does not go out
const missing=FIXED.filter(e=>att.indexOf(e)<0);
if(missing.length){throw new Error('REFUSED: invite is missing '+missing.join(', ')+' - Aditya 28 Sep: all five (Aditya, Shradhaa, Chaman, founder, investor) are compulsory on every dealflow meeting');}
const ev={summary:b.summary,description:b.description||'',start:{dateTime:b.start,timeZone:'Asia/Kolkata'},end:{dateTime:b.end,timeZone:'Asia/Kolkata'},attendees:att.map(e=>({email:e})),conferenceData:{createRequest:{requestId:'sv-'+Date.now(),conferenceSolutionKey:{type:'hangoutsMeet'}}}};
if(b.dry!==false){throw new Error('DRY OK | '+JSON.stringify(ev));}
return [{json:{ev}}];
